//! Static content extracted from the Python game at commit 9b02494.
//!
//! `data/content.json` is generated by `tools/extract_content.py`. The sim
//! reads it with `include_str` so the crate has no runtime data-file dependency.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

